package cn.zhuatech.clm.controller; import cn.zhuatech.clm.common.ApiResponse; import cn.zhuatech.clm.dto.ClmDto.*; import cn.zhuatech.clm.service.ClmService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/shopfloor") @PreAuthorize("hasAnyRole('CONTRACT_SPECIALIST','ADMIN')") public class ContractSpecialistController {private final ClmService service;public ContractSpecialistController(ClmService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.shopfloorDashboard());}@PostMapping("/work-orders/{id}/reports") public ApiResponse<ReportResult> report(@PathVariable Long id,@Valid @RequestBody ReportRequest request){return ApiResponse.ok("反馈提交成功",service.report(id,request));}}
